<script setup>
import {ref,watch} from 'vue'
import {request} from '../api'
import MathText from './MathText.vue'
const props=defineProps({user:Object,group:Object,joined:Boolean})
const opened=ref(false),question=ref(''),answer=ref(''),error=ref(''),busy=ref(false),consent=ref(false),planning=ref(false),planDay=ref(''),saved=ref(false)
const history=ref([])
async function loadHistory(){const version=epoch;try{const result=await request('identity','/advisor/history?group_id='+encodeURIComponent(props.group.id));if(version===epoch)history.value=result.slice().reverse()}catch(e){if(version===epoch)error.value=e.message}}
async function clearHistory(){await request('identity','/advisor/history?group_id='+encodeURIComponent(props.group.id),'DELETE');history.value=[];answer.value=''}
watch(opened,value=>{if(value&&props.joined)loadHistory()})
let epoch=0
watch(()=>[props.user?.id,props.group?.id],()=>{epoch++;busy.value=false;history.value=[];opened.value=false;answer.value='';planDay.value='';saved.value=false;question.value='';error.value='';consent.value=false})
async function ask(){const version=epoch;busy.value=true;error.value='';answer.value='';planDay.value='';saved.value=false;try{if(!consent.value)throw Error('请先确认发送上下文');const data=planning.value?await request('identity','/learning/next-day-plan','POST',{consent:true,group_id:props.group.id}):await request('identity','/advisor/messages','POST',{group_id:props.group.id,question:question.value,consent:'share-group-context'});if(version===epoch){answer.value=data.answer;planDay.value=data.learning_day||'';saved.value=false;if(!planning.value)await loadHistory()}}catch(e){if(version===epoch)error.value=e.message}finally{if(version===epoch)busy.value=false}}
async function save(){const version=epoch;busy.value=true;error.value='';try{await request('group','/group/learning/plans','PUT',{learning_day:planDay.value,body:answer.value});if(version===epoch)saved.value=true}catch(e){if(version===epoch)error.value=e.message}finally{if(version===epoch)busy.value=false}}
watch(planning,()=>{answer.value='';planDay.value='';consent.value=false;saved.value=false})
function plan(){opened.value=true;if(busy.value){error.value='请求正在处理中，请等待完成再切换';return}planning.value=true;consent.value=false;answer.value='';planDay.value='';saved.value=false}
defineExpose({plan})
</script>
<template><div v-if="user&&group&&joined" class="advisor-floating"><button class="float-trigger" aria-label="快速询问机器人" :aria-expanded="opened" @click="opened=!opened">✦ 顾问</button><section v-if="opened" class="float-window" aria-label="机器人快捷窗口"><div class="section-head"><strong>算法学习顾问</strong><button class="secondary" aria-label="关闭顾问" @click="opened=false">✕</button></div><p class="note">当前检索范围：本群组 · {{group.name}}</p><button v-if="!planning" class="secondary" :disabled="busy" @click="clearHistory">清空会话</button><label>用途<select v-model="planning" :disabled="busy"><option :value="false">快速询问当前群组</option><option :value="true">规划下一天学习目标</option></select></label><p v-if="!planning&&!joined">先连接群组，或选择次日规划。</p><textarea v-if="!planning" v-model="question" maxlength="4000" placeholder="快速询问算法问题"></textarea><label class="consent"><input v-model="consent" type="checkbox"><span>{{planning?'允许将本群组中我的最近 7 条学习提交、打卡与 OJ 验证记录发送给已配置模型':'允许将问题、本群组讨论、资料、我的学习记录和近期会话发送给已配置模型'}}</span></label><button :disabled="busy||!consent||(!planning&&(!joined||!question.trim()))" @click="ask">{{busy?'生成中…':planning?'生成明日目标':'询问'}}</button><p v-if="error" class="error" role="alert">{{error}}</p><article v-for="(turn,index) in history" v-show="!planning" :key="index" class="chat-turn"><p><strong>我：</strong>{{turn.QUESTION}}</p><MathText :text="turn.ANSWER"/></article><MathText v-if="answer&&planning" class="answer" :text="answer"/><button v-if="planning&&answer" :disabled="busy||saved" @click="save">{{saved?'已保存，可在每日学习页刷新查看':'保存为明日目标'}}</button></section></div></template>
<style scoped>.advisor-floating{position:fixed;right:24px;bottom:24px;z-index:25}.float-trigger{box-shadow:0 4px 18px #24344b30}.float-window{position:absolute;bottom:58px;right:0;width:min(500px,calc(100vw - 40px));max-height:75vh;overflow:auto;background:white;padding:20px;border:1px solid #e4e9f0;border-radius:12px;box-shadow:0 12px 40px #24344b24}.answer{white-space:pre-wrap;overflow-wrap:anywhere;background:#edf0ff;padding:12px}.float-window select{width:100%}</style>
